// Secure application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet());

// CORS configuration (adjust origins as needed)
const corsOptions = {
  origin: process.env.CORS_ORIGIN || '*', // Configure via env in production
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting - configurable via environment variables
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // 15 minutes default
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100'),     // 100 requests default
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,  // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Parse JSON bodies
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: process.env.SERVICE_NAME || 'user-service',
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with basic validation
app.get('/users', (req, res) => {
  // In a real app, you might validate/query parameters here
  // For example: validate pagination, search terms, etc.

  // Sample data - in production this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    success: true,
    count: users.length,
    data: users
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: 'The requested resource could not be found'
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak stack trace in production
  const errorResponse = {
    success: false,
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  };

  // Include error ID for tracking in production
  if (process.env.NODE_ENV !== 'development') {
    errorResponse.errorId = 'ERR-' + Math.random().toString(36).substr(2, 9);
  }

  res.status(500).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

